import 'package:cross_platform_video_thumbnails/cross_platform_video_thumbnails.dart';

void main() async {
  await CrossPlatformVideoThumbnails.initialize();
  final thumb = await CrossPlatformVideoThumbnails.generateThumbnail(
    'assets/video.mp4',
    ThumbnailOptions(timePosition: 5.0, width: 320, height: 240, format: ThumbnailFormat.jpeg),
  );
  print('Thumbnail size: ${thumb.size} bytes');
}
